/**
 * AI Red-Team Session Log — tool-local actions.
 *
 * Category: AI / LLM Product Management (squad S12b)
 * Tool:     Record adversarial-prompt sessions — attack vector, whether it
 *           succeeded, severity, mitigation, and a retest due-date.
 *
 * Agent surface: tool.ai_red_team.*
 * Backing CRUD : workspace.red_team_finding.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see hallucination-log.ts for the analog) ──
 * Findings are a record-keeping entity — generic create / list / update /
 * delete already exist via the auto-generated workspace.red_team_finding.*
 * surface. This file adds the VERBS THE AGENT WANTS TO SPEAK in the
 * red-team domain, plus one pure compute:
 *
 *   1. list_state           — snapshot + breakdowns (bySeverity, open vs
 *                             resolved, successful-attack count + rate,
 *                             how many are due for retest).
 *   2. compute_exposure     — pure: open + successful findings weighted by
 *                             severity → a single "exposure" number the
 *                             agent can reason about without a mutation.
 *   3. log_finding          — record a red-team finding (loggedAt defaults
 *                             to now). Additive, no confirmation.
 *   4. mark_resolved        — close a finding: stamp resolvedAt AND record
 *                             the mitigation that closed it (required — a
 *                             closed finding with no mitigation loses the
 *                             learning, mirroring hallucination-log).
 *
 * Entity kind "workspace:redTeamFinding" (camelCase via kindFromToolId of
 * "workspace.red_team_finding") matches the browser sync engine + the
 * generic CRUD surface, so MCP writes round-trip into the UI byte-for-byte.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { RedTeamFinding } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.red_team_finding")
 *  used by the auto-generated CRUD, so reads/writes here line up byte-for-byte
 *  with the generic surface and the browser sync engine. */
const KIND_RED_TEAM = "workspace:redTeamFinding";

/** Closed enum of valid severities. Matches the literal union in
 *  workspace-types.ts:RedTeamFinding.severity verbatim. */
const SEVERITIES = ["low", "medium", "high", "critical"] as const;
const SeveritySchema = z.enum(SEVERITIES);

/** Severity weights for the exposure score. A successful critical attack is
 *  ~15x the operational risk of a low one — the same tiering the
 *  hallucination-log uses for its burden score, kept consistent so an agent
 *  reasoning across both AI-quality tools sees comparable magnitudes. */
const SEVERITY_WEIGHT: Record<RedTeamFinding["severity"], number> = {
  low: 1,
  medium: 3,
  high: 7,
  critical: 15,
};

const ws = () => useWorkspaceStore.getState();

/** Build the {bySeverity, openCount, resolvedCount, successfulCount,
 *  successRate, dueForRetestCount, items} response. One helper so the
 *  browser-path and MCP-path responses can't drift. */
function summarize(items: RedTeamFinding[]) {
  const bySeverity: Record<RedTeamFinding["severity"], number> = {
    low: 0,
    medium: 0,
    high: 0,
    critical: 0,
  };
  let openCount = 0;
  let resolvedCount = 0;
  let successfulCount = 0;
  let dueForRetestCount = 0;
  const now = Date.now();

  for (const f of items) {
    // Defensive: a hand-crafted entity with an out-of-enum severity would
    // otherwise NaN the bucket. The row still appears in `items`.
    if (f.severity in bySeverity) bySeverity[f.severity] += 1;
    if (f.resolvedAt) resolvedCount += 1;
    else openCount += 1;
    if (f.successful) successfulCount += 1;
    // A retest is "due" when it has a due-date in the past and the finding
    // isn't already resolved. Unparseable dates are skipped, not counted.
    if (!f.resolvedAt && f.retestDueAt) {
      const due = Date.parse(f.retestDueAt);
      if (!Number.isNaN(due) && due <= now) dueForRetestCount += 1;
    }
  }

  return {
    total: items.length,
    bySeverity,
    openCount,
    resolvedCount,
    successfulCount,
    // Share of all logged findings where the attack actually succeeded.
    // 0 when there are no findings (avoids NaN).
    successRate: items.length ? Math.round((successfulCount / items.length) * 100) / 100 : 0,
    dueForRetestCount,
    items,
  };
}

// ──────── tool.ai_red_team.list_state ────────
registry.register({
  id: "tool.ai_red_team.list_state",
  toolId: "tool.ai_red_team",
  name: "list_state",
  category: "read",
  description:
    "List all red-team findings with summary breakdowns. Returns {total, bySeverity: {low, medium, high, critical}, openCount, resolvedCount, successfulCount, successRate (0..1, share of findings where the attack succeeded), dueForRetestCount (open findings whose retestDueAt is in the past), items}.",
  paramsSchema: z.object({}),
  handler: async () => summarize(ws().redTeamFindings ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<RedTeamFinding>(ctx.userId, KIND_RED_TEAM);
    return summarize(items);
  },
});

// ──────── tool.ai_red_team.compute_exposure ────────
// Pure: open + successful findings contribute their severity weight
// (low=1, medium=3, high=7, critical=15). Resolved findings, and failed
// attacks (the model defended), contribute 0. Lets the agent ask
// "how exposed are we right now?" or "what if we resolved the criticals?"
// against trial data without mutating anything. No mcpHandler — pure.
registry.register({
  id: "tool.ai_red_team.compute_exposure",
  toolId: "tool.ai_red_team",
  name: "compute_exposure",
  category: "read",
  description:
    "Compute a numeric exposure score for a batch of red-team findings. Only open AND successful attacks count, weighted by severity (low=1, medium=3, high=7, critical=15); resolved or unsuccessful findings contribute 0. Pure — no persistence.",
  paramsSchema: z.object({
    items: z
      .array(
        z.object({
          severity: SeveritySchema,
          successful: z.boolean(),
          resolvedAt: z.string().optional(),
        })
      )
      .min(0)
      .max(2000),
  }),
  handler: async (params) => {
    let exposureScore = 0;
    for (const it of params.items) {
      // Only an unresolved, successful attack is live exposure.
      if (it.resolvedAt || !it.successful) continue;
      exposureScore += SEVERITY_WEIGHT[it.severity];
    }
    return { exposureScore };
  },
  // No mcpHandler — pure compute runs identically on server and client.
});

// ──────── tool.ai_red_team.log_finding ────────
registry.register({
  id: "tool.ai_red_team.log_finding",
  toolId: "tool.ai_red_team",
  name: "log_finding",
  category: "write",
  requiresConfirmation: false,
  description:
    "Log a red-team finding. `successful` = whether the adversarial prompt actually broke the guardrail. loggedAt defaults to now. Returns {added: true, id}.",
  paramsSchema: z.object({
    attackVector: z
      .string()
      .min(1)
      .max(500)
      .describe("The class of attack, e.g. 'prompt injection'."),
    successful: z.boolean().describe("Did the attack succeed (guardrail bypassed)?"),
    severity: SeveritySchema,
    promptUsed: z.string().max(4000).optional(),
    mitigation: z.string().max(2000).optional(),
    retestDueAt: z.string().optional().describe("ISO date when this should be re-tested."),
    loggedAt: z.string().optional().describe("ISO timestamp; defaults to now when omitted."),
  }),
  handler: async (params) => {
    const finding: RedTeamFinding = {
      id: crypto.randomUUID(),
      attackVector: params.attackVector,
      successful: params.successful,
      severity: params.severity,
      promptUsed: params.promptUsed,
      mitigation: params.mitigation,
      retestDueAt: params.retestDueAt,
      loggedAt: params.loggedAt ?? new Date().toISOString(),
    };
    ws().upsertRedTeamFinding(finding);
    return { added: true, id: finding.id };
  },
  mcpHandler: async (params, ctx) => {
    const finding: RedTeamFinding = {
      id: crypto.randomUUID(),
      attackVector: params.attackVector,
      successful: params.successful,
      severity: params.severity,
      promptUsed: params.promptUsed,
      mitigation: params.mitigation,
      retestDueAt: params.retestDueAt,
      loggedAt: params.loggedAt ?? new Date().toISOString(),
    };
    await serverUpsertEntity<RedTeamFinding>(ctx.userId, KIND_RED_TEAM, finding);
    return { added: true, id: finding.id };
  },
});

// ──────── tool.ai_red_team.mark_resolved ────────
// Close a finding: stamp resolvedAt + record the mitigation that closed it.
// mitigation is required — a resolved finding with no mitigation can't teach
// the next reader what actually fixed the hole (mirrors hallucination-log's
// mark_resolved). Additive (augments, never overwrites) → no confirmation.
registry.register({
  id: "tool.ai_red_team.mark_resolved",
  toolId: "tool.ai_red_team",
  name: "mark_resolved",
  category: "write",
  requiresConfirmation: false,
  description:
    "Mark a red-team finding as resolved. Stamps resolvedAt (defaults to now) and records the mitigation that closed it — mitigation is required. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    mitigation: z
      .string()
      .min(1)
      .max(2000)
      .describe("What was changed to close the finding (guardrail, filter, prompt fix, …)."),
    resolvedAt: z
      .string()
      .optional()
      .describe("ISO timestamp; defaults to the current time when omitted."),
  }),
  handler: async (params) => {
    const items = ws().redTeamFindings ?? [];
    const current = items.find((f) => f.id === params.id);
    if (!current) return { updated: false };
    ws().upsertRedTeamFinding({
      ...current,
      mitigation: params.mitigation,
      resolvedAt: params.resolvedAt ?? new Date().toISOString(),
    });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<RedTeamFinding>(ctx.userId, KIND_RED_TEAM, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<RedTeamFinding>(ctx.userId, KIND_RED_TEAM, {
      ...current,
      mitigation: params.mitigation,
      resolvedAt: params.resolvedAt ?? new Date().toISOString(),
    });
    return { updated: true };
  },
});
